diff --git a/web/src/lib/AdminForm.svelte b/web/src/lib/AdminForm.svelte
index bc28c7f..aeedcdb 100644
--- a/web/src/lib/AdminForm.svelte
+++ b/web/src/lib/AdminForm.svelte
@@ -15,7 +15,7 @@
  function persist(value:string){sessionStorage.setItem(key,value);}
  async function currentIdentity(){const g=generation;let next;try{next=await identity();}catch(error){if(!mounted||g!==generation)throw error;if(error instanceof Error&&error.message==='PERMISSION'){clear();message='Chưa xác nhận được quyền quản trị. Dữ liệu riêng đã được ẩn.';}else{channel='UNKNOWN';message='Chưa kiểm tra được phiên quản trị. Chỉ đọc đối chiếu lại, không tự gửi thao tác.';}throw error;}if(!mounted||g!==generation)throw new Error('SESSION_CHANGED');if(!who||next.actor!==who.actor||next.epoch!==who.epoch){clear();message='Phiên đã thay đổi. Dữ liệu cũ đã được ẩn; hãy tải lại trang.';throw new Error('SESSION_CHANGED');}who=next;if(message==='Chưa kiểm tra được phiên quản trị. Chỉ đọc đối chiếu lại, không tự gửi thao tác.')message='Đã kiểm tra lại phiên quản trị. Thao tác vẫn được đối chiếu trước khi gửi.';}
  async function snapshot(){if(!initial)return null;const v=decodeAdmin(await json('/admin/workshops/'+encodeURIComponent(initial.id)));if(!v||v.id!==initial.id||v.epoch!==who?.epoch)throw new Error('SNAPSHOT');return v;}
- async function refresh(replace=false,background=false){const g=generation;await currentIdentity();const next=await snapshot();if(!mounted||g!==generation||background&&busy)return false;return observe(next,replace,background);}
+ async function refresh(replace=false,background=false){const g=generation;await currentIdentity();const next=await snapshot();await currentIdentity();if(!mounted||g!==generation||background&&busy)return false;return observe(next,replace,background);}
  function observe(next:AdminSnapshot|null,replace=false,background=false){
   if(base&&next){const order=compareAdminObservation(base,next);if(order==='OLDER')return false;if(order==='CONFLICT'){blockConflict();return false;}}
   if(conflicted&&background)return false;conflicted=false;
@@ -50,8 +50,8 @@
    if(confirmationLines.length){candidate=command;dialog.showModal();return;}await send(command);
   }catch{message='Chưa xác nhận phiên hoặc dữ liệu hiện tại. Chưa gửi thao tác.';}finally{busy=false;}
  }
- async function confirm(){if(!candidate||busy||!base||!who)return;busy=true;const command=candidate;const before=base;candidate=null;dialog.close();
-  try{await currentIdentity();const current=await snapshot();if(current&&compareAdminObservation(before,current)==='CONFLICT'){blockConflict();return;}if(!current||!sameObservation(before,current)){latest=current;message='Dữ liệu thay đổi trong lúc xác nhận. Hãy xem lại trước khi gửi.';return;}await send(command);}catch{message='Chưa xác nhận dữ liệu mới. Chưa gửi thao tác.';}finally{busy=false;}
+ async function confirm(){if(!candidate||busy||!base||!who)return;busy=true;const g=generation;const command=candidate;const before=base;candidate=null;dialog.close();
+  try{await currentIdentity();const current=await snapshot();await currentIdentity();if(!mounted||g!==generation||!who)return;if(current&&compareAdminObservation(before,current)==='OLDER'){message='Bản đọc cũ hơn dữ liệu đã biết. Hãy tải và đối chiếu lại trước khi gửi.';return;}if(current&&compareAdminObservation(before,current)==='CONFLICT'){blockConflict();return;}if(!current||!sameObservation(before,current)){latest=current;message='Dữ liệu thay đổi trong lúc xác nhận. Hãy xem lại trước khi gửi.';return;}await send(command);}catch{if(mounted&&g===generation)message='Chưa xác nhận dữ liệu mới. Chưa gửi thao tác.';}finally{busy=false;}
  }
  onMount(()=>{mounted=true;const g=++generation;
   void(async()=>{try{const session=await identity();if(!mounted||g!==generation)return;who=session;contentKey='workshop-admin-content:'+session.actor+':'+session.epoch+':'+(initial?.id??'CREATE');key='workshop-admin:'+session.actor+':'+session.epoch+':'+(initial?.id??'CREATE');base=await snapshot();await currentIdentity();if(!mounted||g!==generation)return;draft=formOf(base);const saved=sessionStorage.getItem(key);if(saved){const restored=decodeAdminIntent(saved,session.actor,session.epoch);if(!restored){message='Mã đối chiếu đã lưu không hợp lệ. Chưa thể tạo thao tác thay thế.';return;}intent=restored;}await restoreContent();if(!mounted||g!==generation||!who)return;ready=true;if(initial){stopUpdates=openUpdates({audience:'admin',epoch:session.epoch,workshopId:initial.id,csrf:()=>who?.csrf??'',validate:async()=>{const before=generation;await currentIdentity();return mounted&&before===generation;},read:()=>json('/admin/workshops/'+encodeURIComponent(initial.id)),snapshot:(raw,source)=>{const next=decodeAdmin(raw);if(!next||next.id!==initial.id||next.epoch!==who?.epoch||busy)return false;return observe(next,false,source==='SOCKET');},status:value=>{if(mounted)channel=value;}});}message=unresolved?'Có thao tác chưa xác nhận. Chỉ đọc kết quả cùng mã; không gửi lại.':'Có thể chỉnh sửa. Trạng thái được kiểm lại trước khi gửi.';}catch{if(mounted&&g===generation){clear();message='Chưa xác nhận được phiên hoặc dữ liệu quản trị.';}}})();
